<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Revisão de Compliance | AssessorGov IA</title><style>body{font-family:Inter,system-ui;background:#07111f;color:#f4f7fb;margin:0;padding:28px}.wrap{max-width:1100px;margin:auto}.card{background:#0d1b2d;border:1px solid #243b58;border-radius:16px;padding:20px;margin:16px 0}.muted{color:#aebed0}.tag{font-size:12px;font-weight:800}.btn{background:#36d399;color:#032016;border:0;border-radius:9px;padding:9px 12px;font-weight:800}select,textarea{width:100%;margin:8px 0;padding:9px;background:#07111f;color:#f4f7fb;border:1px solid #243b58;border-radius:8px}textarea{min-height:80px}</style></head><body><div class="wrap"><h1>Fila de revisão de Compliance</h1><p class="muted">Declaração do cliente e validação são etapas separadas.</p>@if(session('status'))<div class="card">{{ session('status') }}</div>@endif @forelse($items as $item)<div class="card"><span class="tag">{{ strtoupper($item->status) }} · {{ strtoupper($item->priority) }}</span><h3>{{ $item->title }}</h3><p>{{ $item->action }}</p><p class="muted">Cliente: {{ $item->customer?->trade_name ?: $item->customer?->legal_name }} · enviado em {{ $item->submitted_at?->format('d/m/Y H:i') ?: '—' }}</p>@if($item->latestEvidence)<p class="muted">Evidência: {{ $item->latestEvidence->original_name }} · SHA-256 registrado</p>@endif<form method="POST" action="{{ route('gov.compliance.review.update', $item) }}">@csrf @method('PUT')<select name="status" required><option value="in_review">Colocar em análise</option><option value="conformant">Validar como conforme</option><option value="rejected">Rejeitar / devolver</option></select><textarea name="review_note" placeholder="Parecer ou motivo da decisão"></textarea><button class="btn" type="submit">Registrar revisão</button></form></div>@empty<div class="card muted">Nenhum item aguardando revisão.</div>@endforelse</div></body></html>
